head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
scwin.MSG_50M_LOW = '신탁원본액 50억미만에 해당됩니다.';
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.getPar, scwin.setPar;
scwin.TR_JOB;
scwin.VListBzTpCd = LIST_BZ_TP_CD_142; // ETF 변경상장

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // var parentWin = fn_GetProvider();
        const parentWin = $c.frame.path("../");
        // alert('[parentWin]'+parentWin);
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vAcptNo = parentWin.scwin.vAcptNo;
        scwin.vIsurCd = parentWin.scwin.vIsurCd;
        scwin.vOpenTyp = parentWin.scwin.vOpenTyp;
        txb_ISU_CD.setValue(parentWin.txb_ISU_CD.getValue());
        txb_ISU_NM.setValue(parentWin.txb_ISU_NM.getValue());
        $c.libRoundPanel.PanelToGroupBox(panel_Item);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성s
        // buttonSet.setDrftInfo( btn_Drft, fn_drft );            // 기안

        if (scwin.vOpenTyp === "R") {
            await scwin.recvReadSync();
        } else if (scwin.vOpenTyp === "H") {
            await scwin.readSync();
        } else if (scwin.vOpenTyp === "N") {
            await scwin.bfReadSync();
            scwin.initItem();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05306.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_DELETE_OnLoadError
 * @description dts_DELETE 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DELETE_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DELETE);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05306.dts_DELETE_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05306.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_RecvIsuDel_onclick
 * @description 「신청종목삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RecvIsuDel_onclick = async function() {
    try {
        await scwin.recvtIsuDel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05306.btn_RecvIsuDel_onclick" });
    }
};

/**
 * @method
 * @name edt_INCDEC_LIST_SHRS_onkillfocus
 * @description edt_INCDEC_LIST_SHRS onkillfocus 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_INCDEC_LIST_SHRS_onkillfocus = async function() {
    try {
        await scwin.calcuate();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05306.edt_INCDEC_LIST_SHRS_onkillfocus" });
    }
};

/**
 * @method
 * @name img_BENFCERT_ESTBREPUR_DD_onclick
 * @description img_BENFCERT_ESTBREPUR_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BENFCERT_ESTBREPUR_DD_onclick = function() {
    try {
        popUpCalendar2(edt_BENFCERT_ESTBREPUR_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05306.img_BENFCERT_ESTBREPUR_DD_onclick" });
    }
};

/**
 * @method
 * @name img_LIST_DD_onclick
 * @description img_LIST_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_LIST_DD_onclick = function() {
    try {
        popUpCalendar2(edt_LIST_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05306.img_LIST_DD_onclick" });
    }
};

/**
 * @method
 * @name img_TRST_DISTR_PAY_BAS_DD_onclick
 * @description img_TRST_DISTR_PAY_BAS_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_TRST_DISTR_PAY_BAS_DD_onclick = function() {
    try {
        popUpCalendar2(edt_TRST_DISTR_PAY_BAS_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05306.img_TRST_DISTR_PAY_BAS_DD_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05306.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vOpenTyp === "N" || (scwin.vOpenTyp === "R" && scwin.vBzProcsNo === '')) {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_LIST_DD, false);
            $c.stf.setButtonSetWithDate2(dts_Isu.getCellData(1, "DISCLS_YN"));
        }
        if (scwin.vOpenTyp === "R" && scwin.vBzProcsNo === "") {
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel.gif");
            btn_RecvIsuDel.setDisabled(false);
        } else {
            btn_RecvIsuDel.setBackgroundImage("../img/btn_RcvdocDel_d.gif");
            btn_RecvIsuDel.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05306.dts_Isu_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05306.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh(); // 목록 다시 조회
        if (scwin.TR_JOB === 'D') {
            await $c.win.closePopup();
        } else {
            await scwin.readSync();
            buttonSet.setUpdateStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05306.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name bfReadSync
 * @description bf Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bfReadSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05306.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_ETF_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL2 + "&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name recvReadSync
 * @description recv Read Sync 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvReadSync = async function(row) {
    url += "?SCREN_ID=" + "ULDSTF05306.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_ETF_RECV + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&ACPT_NO=" + scwin.vAcptNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.initItem();
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05306.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_ETF_HIST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Listing.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // jackal_11.05.12
    // if ( (dts_Isu.NameString(1, "ETF_NETASST_TOTAMT")) <  5000000000 ) {
    //    alert(MSG_50M_LOW);
    // }

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (scwin.TR_JOB === 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    // alert("[fn_trs vBzProcsNo] ."+vBzProcsNo);
    // dts_Isu.NameValue(1, "JOB_TYPE") = trsIdx;
    dts_Isu.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Isu.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
    dts_Isu.setCellData(1, "LIST_BZ_TP_CD", scwin.VListBzTpCd);
    // alert('[dts_Isu]'+dts_Isu.text);

    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     ACPT_NO : scwin.vAcptNo,
    //     BYACPTNO_SEQ : "1",
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     COUNT : "1",
    //     LIST_BZ_TP_CD : scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_CHG_ISS_ETF_HIST
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/Listing.do",
        ref : "dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name recvtIsuDel
 * @description recvt Isu Del 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.recvtIsuDel = async function() {
    if (scwin.vAcptNo === "") {
        await $c.win.alert('발행예정내역에서 대상종목을 선택하세요');
        return;
    }
    scwin.TR_JOB = 'D';
    if (!window.confirm($c.stf.getMessageParam('MSG-A006', "신청종목삭제"))) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Isu.setCellData(1, "ISUR_CD", scwin.vIsurCd);
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TRS_IDX_DELETE2,
        //     ACPT_NO : scwin.vAcptNo,
        //     BYACPTNO_SEQ : "1",
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     COUNT : "1",
        //     LIST_BZ_TP_CD : scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_LIST_APPL_FORM_DEL
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/Listing.do",
            ref : "dts_Isu",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initItem
 * @description init Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    cmb_LIST_METHD_TP_CD.setValue(LIST_METHD_TP_CD_3);
    edt_TRST_DISTR_PAY_BAS_DD.setValue($c.ut.cGetToday("yyyymmdd").substring(0, 4) + "0101");
};

/**
 * @method
 * @name calcuate
 * @description calcuate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuate = async function() {
    try {
        const vsum = parseInt(edt_BF_LIST_SHRS.getValue()) + parseInt(edt_INCDEC_LIST_SHRS.getValue());
        edt_LIST_SHRS.setValue(vsum);

        // fn_50mcalcuate(); jackal_11.05.12

    } catch (err) {
        await $c.win.alert("[증권수 합산처리 중  오류]");
    }
};

/**
 * @method
 * @name fn_50mcalcuate
 * @description 50mcalcuate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fn_50mcalcuate = async function() {
    if ((edt_LIST_SHRS.getValue() * dts_Isu.getCellData(1, "ISU_PRC")) < 5000000000) {
        await $c.win.alert(scwin.MSG_50M_LOW);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= edt_LIST_DD.getValue()) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (edt_BENFCERT_ESTBREPUR_DD.getValue() === "") {
        await $c.win.alert("[설정및환매일]을 입력하세요.");
        edt_BENFCERT_ESTBREPUR_DD.focus();
        return false;
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === "") {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if (edt_INCDEC_LIST_SHRS.getValue() === "") {
        await $c.win.alert("[증감증권수]을 입력하세요.");
        edt_INCDEC_LIST_SHRS.focus();
        return false;
    }
    if (!await scwin.checkNumber(edt_INCDEC_LIST_SHRS, '증감증권수')) return false;
    if (edt_LIST_SHRS.getValue() === "") {
        await $c.win.alert("[변경후 상장증권수]을 입력하세요.");
        edt_LIST_SHRS.focus();
        return false;
    }
    if (!await scwin.checkNumber(edt_LIST_SHRS, '변경후 상장증권수')) return false;
    if (cmb_ISU_RSN_CONTN.getValue() === "") {
        await $c.win.alert("[변경사유]를 입력하세요.");
        cmb_ISU_RSN_CONTN.focus();
        return false;
    }

    // fn_50mcalcuate(); jackal_11.05.12

    if (edt_TRST_DISTR_PAY_BAS_DD.getValue() === "") {
        await $c.win.alert("[분배지급기준일]을 입력하세요.");
        edt_TRST_DISTR_PAY_BAS_DD.focus();
        return false;
    }
    if (txa_REMK.getValue().length > 500) {
        await $c.win.alert("[기타]항목이 입력사이즈를 초과하였씁니다.");
        txa_REMK.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name checkNumber
 * @description check Number 처리
 * @param {Object} obj 컴포넌트
 * @param {String} str str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNumber = async function(obj, str) {
    /* etf는 환매시 0보다 작은값이들어감.
    if (getObjectValue(obj) <= 100) {
    	alert("["+str+"]를 '"+getObjectValue(obj)+"'으로 입력하셨습니다. 확인 후 재입력바랍니다.");obj.focus();return false;
    }
     */
    if (obj.getValue() === 0) {
        await $c.win.alert("[" + str + "]를 '" + obj.getValue() + "'으로 입력하셨습니다. 확인 후 재입력바랍니다.");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            // dts_Isu.UserStatus(1) = TB_JOB_INSERT;
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TRS_IDX_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;

    // 삭제시 공시 배포여부에 대한 확인 20100419
    if (!$c.lc.fn_check_delete_discls(dts_DELETE, dts_Isu.getCellData(1, "BZ_PROCS_NO"))) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    await scwin.trs(TRS_IDX_DELETE);
};

